package xiaozhi.modules.diagnostics;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.mock.env.MockEnvironment;
/** Fast real SQL projection fixture in one new retained schema; no provider calls or application data changes. */
@EnabledIfEnvironmentVariable(named="AI_OPERATIONS_TEST_JDBC_URL",matches=".+")
class AiOperationsDiagnosticsPersistenceTest {
    @Test void realSqlCountsOldStallsSanitizesRevocationAndRequiresAnActualRealtimeReply()throws Exception {
        String url=System.getenv("AI_OPERATIONS_TEST_JDBC_URL");if(!url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/xiaozhi_ai_operations_test_[a-z0-9_]+(\\?.*)?"))throw new IllegalArgumentException("Only a NEW retained operations test schema is allowed");var db=new JdbcTemplate(new DriverManagerDataSource(url,"root",System.getenv("AI_OPERATIONS_TEST_DB_PASSWORD")));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()",Long.class));
        db.execute("CREATE TABLE sys_user(id BIGINT PRIMARY KEY,status TINYINT,super_admin TINYINT)");db.update("INSERT INTO sys_user VALUES(1,1,1),(2,1,0),(3,0,1)");
        db.execute("CREATE TABLE ai_run(id VARCHAR(50),status VARCHAR(30),error_code VARCHAR(300),created_at DATETIME(3),updated_at DATETIME(3),lease_expires_at DATETIME(3))");
        db.execute("CREATE TABLE ai_realtime_session(id VARCHAR(50),status VARCHAR(30),error_code VARCHAR(300),created_at DATETIME(3),ended_at DATETIME(3),lease_expires_at DATETIME(3))");db.execute("CREATE TABLE ai_realtime_turn(kind VARCHAR(30),status VARCHAR(30),ended_at DATETIME(3))");
        db.execute("CREATE TABLE ai_realtime_material(id VARCHAR(50),session_id VARCHAR(50),status VARCHAR(30),error_code VARCHAR(300),created_at DATETIME(3),updated_at DATETIME(3),dispatched_at DATETIME(3),prepared_at DATETIME(3))");db.execute("CREATE TABLE ai_answer_speech_job(id VARCHAR(50),attempt INT,status VARCHAR(30),error_code VARCHAR(300),created_at DATETIME(3),updated_at DATETIME(3))");db.execute("CREATE TABLE ai_answer_speech_attempt(job_id VARCHAR(50),attempt INT,lease_expires_at DATETIME(3),dispatched_at DATETIME(3))");
        db.update("INSERT INTO ai_run VALUES('private-resource-id','queued',NULL,DATE_SUB(NOW(3),INTERVAL 3 HOUR),DATE_SUB(NOW(3),INTERVAL 3 HOUR),NULL)");for(int i=0;i<3;i++)db.update("INSERT INTO ai_run VALUES(?,'failed','PROVIDER_TIMEOUT',NOW(3),NOW(3),NULL)","provider-"+i);db.update("INSERT INTO ai_run VALUES('secret-failure','failed','https://private-host/prompt?api_key=secret',NOW(3),NOW(3),NULL)");
        db.update("INSERT INTO ai_realtime_session VALUES('empty-connection','ended',NULL,NOW(3),NOW(3),NULL),('material-parent','active',NULL,NOW(3),NULL,DATE_ADD(NOW(3),INTERVAL 45 SECOND)),('revoked','expired','EXTERNAL_MEDIA_AUTHORIZATION_REVOKED',NOW(3),NOW(3),NULL)");
        db.update("INSERT INTO ai_realtime_material VALUES('material-secret','material-parent','prepared',NULL,DATE_SUB(NOW(3),INTERVAL 2 HOUR),NOW(3),NOW(3),DATE_SUB(NOW(3),INTERVAL 20 SECOND))");db.update("INSERT INTO ai_answer_speech_job VALUES('speech-secret',1,'synthesizing',NULL,DATE_SUB(NOW(3),INTERVAL 2 HOUR),NOW(3))");db.update("INSERT INTO ai_answer_speech_attempt VALUES('speech-secret',1,DATE_SUB(NOW(3),INTERVAL 30 MINUTE),DATE_SUB(NOW(3),INTERVAL 2 HOUR))");
        var env=new MockEnvironment().withProperty("features.conversation-enabled","true").withProperty("features.ai-text-enabled","true").withProperty("features.realtime-ai-enabled","true").withProperty("features.realtime-materials-enabled","true").withProperty("features.answer-speech-enabled","true").withProperty("realtime.materials.perception-model","qwen3.8-flash");var service=new AiOperationsDiagnosticsService(db,env);var summary=service.snapshot(1);var flows=(Map<?,?>)summary.get("flows");var ai=(Map<?,?>)flows.get("ai");assertEquals(1L,ai.get("queue_overdue"));assertTrue(ai.get("error_groups_60m").toString().contains("other"));assertEquals(3L,((List<Map<String,Object>>)summary.get("alerts")).stream().filter(item->item.get("code").equals("PROVIDER_FAILURE_CONCENTRATION")).findFirst().orElseThrow().get("count"));
        var rt=(Map<?,?>)flows.get("realtime");assertNull(rt.get("observed_last_success_at"),"An empty ended connection is not evidence of a model reply");assertEquals(1L,((Map<?,?>)rt.get("outcomes_60m")).get("canceled"));assertEquals(0L,((Map<?,?>)rt.get("outcomes_60m")).get("failed"));assertEquals(List.of(Map.of("group","authorization","count",1L)),rt.get("error_groups_60m"));assertEquals(1L,((Map<?,?>)flows.get("speech")).get("expired_leases"));assertEquals(1L,((Map<?,?>)flows.get("material")).get("expired_leases"));assertTrue((Boolean)((Map<?,?>)((Map<?,?>)flows.get("material")).get("configuration")).get("model_configured"));
        String wire=new xiaozhi.modules.security.config.WebMvcConfig().jackson2HttpMessageConverter().getObjectMapper().writeValueAsString(summary);for(String secret:List.of("private-resource-id","private-host","api_key","speech-secret","material-secret","qwen3.8-flash"))assertFalse(wire.contains(secret));db.update("INSERT INTO ai_realtime_turn VALUES('assistant','completed',NOW(3))");assertNotNull(((Map<?,?>)((Map<?,?>)service.snapshot(1).get("flows")).get("realtime")).get("observed_last_success_at"));var access=new ServerDiagnosticsService(db,env);assertTrue(access.administrator(1));assertFalse(access.administrator(2));assertFalse(access.administrator(3));
    }
}
